     corners.resize(0);
     corners.reserve(1<<(dim-1));
     const index_t dir = direction();
     const bool    par = parameter();
     for (boxCorner c=boxCorner::getFirst(dim); c<boxCorner::getEnd(dim);++c)
     {
         if (c.parameters(dim)(dir) == par)
             corners.push_back(c);
     }
 }

