        const index_t br = nr-r-1;
        const index_t bc = nc-piv-1;
        M.block(r+1, piv+1, br, bc).noalias() -=
            M.col(piv).tail(br) * M.row(r).tail(bc) / M(r, piv);
        M.col(piv).tail(br).setZero();
    }
}

